import"./NZTpNUN0.js";import"./BkvxQF8z.js";import{t as i,P as o,q as r}from"./D3cAVrQp.js";var n=i('<h1>Peace and Conflict Resolution Framework v1.8.1</h1> <h2>Voluntary Prevention, Mediation, Ceasefire Support, Reconciliation, and Just Peacebuilding</h2> <p><strong>Status:</strong> Controlled cluster-conformance successor<br> <strong>Version:</strong> 1.8.1<br> <strong>Supersedes:</strong> Peace and Conflict Resolution Framework v1.8 for future adoption; v1.7 remains historical source<br> <strong>Date:</strong> 2026-08-01<br> <strong>Tier:</strong> Application framework</p> <h3>Controlling interfaces</h3> <ul><li>Security, Coercion, and Protective Action Interface Specification v0.1 (<code>SCPA/0.1</code>) — primary;</li> <li>Justice Systems Framework v1.4 — justice;</li> <li>Aurora Accord v1.3 — data;</li> <li>Synoptic Protocol v4.2 — public information;</li> <li>Genesis Protocol v0.9 — implementation.</li></ul> <h3>Version history</h3> <ul><li><strong>Editorial edition (2026-08-02).</strong> No substantive change. Added this version history, which the document previously lacked; entries below are reconstructed from the document’s own text, and earlier editions remain to be recorded. Converted the five separate interface labels into a single controlling-interfaces section matching the rest of the cluster, and added a Tier line, which was missing. The v1.8 entry below is drawn from the existing change log at Appendix F, which is retained. Digests are unchanged: they are load-bearing here, since the fail-closed rules depend on exact version identity.</li> <li><strong>1.8.1 (2026-08-01):</strong> Controlled conformance patch. Normatively adopts <code>SCPA-RIC/0.1</code>, <code>CFPAE/0.1</code>, <code>ESDIB/0.1</code>, and the exact security-and-coercion cluster release set <code>SCCA/0.1</code>, with digests recorded in the cluster-harmonization appendix. Changes interface adoption, record inheritance, transport, cross-framework responsibility, emergency linkage, pairwise specialization, and exact release compatibility. Adds no police, intelligence, investigation, search, custody, force, cyber, border, sanctions, or prosecutorial authority. Documented at Appendix G.</li> <li><strong>1.8:</strong> Constitutional revision, recorded in full at Appendix F. Replaced the framework-created Global Peace Council with a non-sovereign Peace Support Commons. Removed automatic or mandatory GCRSD roles and spiritual-percentage triggers, Spiral Dynamics and developmental labels from operational classification, AI conflict prediction from intelligence systems, fixed trust, cohesion, approval, and values-transformation targets, and peace-enforcement and sanctions functions. Separated mediation, ceasefire, truth, justice, security, migration, community safety, and reconstruction. Added SCPA-compliant urgent-protection and referral firewalls; protection for mediation, trauma, spiritual, survivor, migration, child, and Indigenous information; 35 operational records, 44 SCPA mappings, 24 readiness gates, and 30 compound tests; and explicit termination, data disposition, correction, remedy, version control, and legitimate non-intervention.</li> <li><strong>Earlier editions:</strong> v1.7 remains the historical source; its history is not yet recorded in this document.</li></ul> <blockquote><p><strong>Peace support may invite, listen, convene, mediate, accompany, verify by consent, help negotiate, preserve memory, support repair, and coordinate reconstruction. It may not investigate, classify, compel, surveil, sanction, detain, adjudicate, command, or enforce merely because peace is at risk.</strong></p> <p><strong>Mediation failure is not a coercive authorization. Developmental, cultural, spiritual, religious, psychological, or ideological interpretation is not a threat determination.</strong></p> <p><strong>No valid authority record, no consequential security or coercive action.</strong></p></blockquote> <hr> <h1>Executive summary</h1> <p>Conflict prevention and peacebuilding require institutions able to listen before violence escalates, help parties communicate, support ceasefires, protect civic space, repair relationships, address structural drivers, preserve memory, accompany communities through transition, and coordinate long-term reconstruction. Those functions are essential. They do not create a right to classify populations, gather intelligence, compel participation, select legitimate political outcomes, direct enforcement, or convert disagreement into dangerousness.</p> <p>Peace v1.8.1 establishes a voluntary, plural, and rights-preserving architecture for:</p> <ul><li>locally requested prevention and dialogue;</li> <li>participatory conflict and structural-condition assessment;</li> <li>diplomatic good offices and mediation;</li> <li>ceasefire negotiation, monitoring, and incident clarification by consent;</li> <li>humanitarian and civilian-protection coordination without command authority;</li> <li>truth, memory, acknowledgement, and reconciliation processes chosen by affected people;</li> <li>reparative and restorative pathways that remain separate from criminal adjudication;</li> <li>post-conflict institutional rebuilding, peace dividends, return, and reintegration;</li> <li>practitioner training, ethical support, and protected learning;</li> <li>careful referral to Justice, Shield, Kintsugi, Migration, emergency, or other systems when a distinct function is genuinely required.</li></ul> <p>The framework retires the source document’s integrated Global Peace Council, compulsory developmental diagnostics, spiritual-percentage referral thresholds, AI conflict prediction feeding a shared intelligence picture, automatic escalation after mediation failure, mandatory GCRSD leadership, peace-enforcement coordination, sanctions as peacebuilding instruments, and composite trust or values-transformation targets.</p> <p>In their place it establishes a <strong>Peace Support Commons</strong>: a non-sovereign federation of locally, regionally, nationally, Indigenous-nation, and internationally constituted support nodes. The Commons maintains standards, rosters, training resources, request routing, protected learning, and optional coordination. It cannot declare a conflict, impose a mediator, determine legitimacy, classify a party, activate security action, negotiate on behalf of a non-consenting people, or become a standing global peace authority.</p> <p>The framework adopts <code>SCPA/0.1</code> as a firewall. Most Peace functions remain within Action Class A—voluntary assistance and prevention. Where facts may require urgent protection, investigation, compulsory process, custody, sanctions, or force, Peace may make a narrowly bounded referral, but the receiving authority must independently establish its own jurisdiction, factual basis, safeguards, review, and remedies. Peace records never supply that authority by themselves.</p> <hr> <h1>1. Source preservation and revision basis</h1> <h2>1.1 Source freeze</h2> <p>This successor was developed from the following pinned documents. No absent annex, institution, legal power, or empirical result was silently supplied.</p> <table><thead><tr><th>Source</th><th align="right">Version</th><th>SHA-256</th></tr></thead><tbody><tr><td>Peace and Conflict Resolution Framework</td><td align="right">v1.7</td><td><code>25add35e4c12f22e15d771543d9d5976189240c20a2a8b86061f76446c11a051</code></td></tr><tr><td>SCPA</td><td align="right">v0.1</td><td><code>b8f1dd0f676044542a23184f52200e50b106a798545c7c57119ded2c439b6299</code></td></tr><tr><td>Justice Systems</td><td align="right">v1.4</td><td><code>08a8fdc78d6cd3928178cb5d98fdf8325b1fd4c9f016bb0c872e6b56b87d3ee4</code></td></tr><tr><td>Shield</td><td align="right">v2.0</td><td><code>4fca33e9ab55574b3255fc36c0a5e81dedd5f2ef6db5f0df3f5887308fbc2b62</code></td></tr><tr><td>Kintsugi</td><td align="right">v2.2</td><td><code>35f06e1449df25c5077c6b7c7b9d6c23f39c499df3d78007951778e91d96c973</code></td></tr><tr><td>Migration</td><td align="right">v1.1</td><td><code>caaf8181b8c519b8df7b87b2d53458b39ffaef6cb33899f7453a56780a8c326d</code></td></tr><tr><td>Aurora Accord</td><td align="right">v1.3</td><td><code>774a86972e527d25edd6a5501235270b7a720483aef83a4e49eb5c96a5a12aa3</code></td></tr><tr><td>Synoptic Protocol</td><td align="right">v4.2</td><td><code>e7f5adbfd8fa10fc10ac9679f2475d2e66bd3ba025fd8e2a8064d31334754cd2</code></td></tr><tr><td>Indigenous Sovereignty and Planetary Healing</td><td align="right">v1.1</td><td><code>2e62ba2c00048ce20e4c9df7ffb9ce0338e358ee866e515bf102f4cc4e49df22</code></td></tr><tr><td>Genesis Protocol</td><td align="right">v0.9</td><td><code>3af8dfe6c90be0f55e80d2c67503440e98f672369f5c5638fd41a80411fa5d49</code></td></tr><tr><td>Work in Liberation</td><td align="right">v2.0</td><td><code>fcc2d12e0e0c22ffc53ff463fbf0f245479238ce34490b06f534c50de4755d68</code></td></tr><tr><td>Treaty for Our Only Home</td><td align="right">v1.3</td><td><code>1a69ccd72fbbc7d16c6bb7f176271b6326e9a47022ae0b3cdadf7caad0946cf4</code></td></tr></tbody></table> <h2>1.2 What is preserved</h2> <p>Version 1.8 preserves the source framework’s strongest commitments:</p> <ol><li>conflict often has material, institutional, historical, relational, cultural, and moral dimensions that cannot be reduced to formal legal claims;</li> <li>prevention, dialogue, mediation, ceasefire support, trauma sensitivity, truth-telling, and reconstruction are distinct but complementary peacebuilding functions;</li> <li>local language, culture, law, ceremony, memory, and community knowledge matter;</li> <li>structural violence, inequality, exclusion, ecological pressure, displacement, and institutional failure can sustain conflict;</li> <li>Indigenous nations and communities require authority over their own lands, knowledge, institutions, and peace processes;</li> <li>spiritual or religious communities may contribute to peace when invited, while secular and non-religious participation must remain equally available;</li> <li>peacebuilding requires long time horizons, failure learning, practitioner care, and material reconstruction;</li> <li>low-tech, offline, multilingual, accessible, and community-controlled modes must remain available;</li> <li>no durable peace can be manufactured solely through elite agreement or coercive stabilization;</li> <li>rebuilding livelihoods, services, housing, land relations, and public institutions is part of peace, not an afterthought.</li></ol> <h2>1.3 What is retired or narrowed</h2> <p>Version 1.8 retires or narrows:</p> <ul><li>the Global Peace Council as a framework-created authority;</li> <li>fixed representation quotas or permanent institutional seats prescribed globally;</li> <li>mandatory GCRSD involvement or leadership;</li> <li>Spiral Dynamics, value-stage, spiritual-driver, cohesion, trust, or trauma scores as allocation, referral, threat, or legal triggers;</li> <li>AI conflict prediction feeding a unified intelligence system;</li> <li>compulsory values mapping or organizational values audits;</li> <li>mandatory escalation after a fixed period of unresolved conflict;</li> <li>peace teams entering a territory or conflict without invitation or valid legal access;</li> <li>mediation as a compulsory prerequisite to justice, asylum, safety, labour rights, or public services;</li> <li>mediation failure as evidence of dangerousness or bad faith;</li> <li>peacebuilding bodies coordinating sanctions, raids, detention, enforcement, or armed action;</li> <li>blockchain-verified agreements as a default or proof of validity;</li> <li>a universal Wisdom Repository or sacred-practice access requirement;</li> <li>social cohesion, trust increase, values transformation, spiritual alignment, or public approval as funding or legitimacy targets;</li> <li>developmental labels such as Red, Blue, Orange, Green, Yellow, Turquoise, Coral, or Clear as person-level or group-level operational classifications.</li></ul> <h2>1.4 Revision objective</h2> <p>The successor places each function at the correct constitutional layer:</p> <ul><li><strong>Peace</strong> supports voluntary prevention, dialogue, negotiation, ceasefire arrangements, reconciliation, and reconstruction.</li> <li><strong>Justice</strong> determines legal rights, duties, liability, evidence, adjudication, appeal, and remedy.</li> <li><strong>Shield</strong> supports lawful transnational crime cooperation and victim protection without becoming a global police authority.</li> <li><strong>Kintsugi</strong> supports community care, survivor sovereignty, unarmed de-escalation, and voluntary restorative pathways.</li> <li><strong>Migration</strong> governs protection, asylum, reception, non-refoulement, status administration, return, and mobility safeguards.</li> <li><strong>SCPA</strong> governs any transition into intelligence, investigation, compulsory process, urgent protection, custody, force, cyber action, financial coercion, mobility consequence, or adjudication.</li> <li><strong>Aegis</strong> governs civilian capability transition and loses civilian status when a proposed use enters security or coercive functions.</li></ul> <hr> <h1>2. Purpose, scope, and non-authority</h1> <h2>2.1 Purpose</h2> <p>Peace v1.8.1 helps affected people, Indigenous nations, public authorities, civil society, mediators, diplomats, humanitarian actors, workers, faith and non-faith communities, youth, displaced persons, survivors, and institutions coordinate peace support without collapsing peacebuilding into intelligence, law enforcement, governance engineering, or social control.</p> <h2>2.2 Scope</h2> <p>The framework covers:</p> <ul><li>locally requested conflict prevention and civic-space support;</li> <li>structural-condition and relationship mapping by consent;</li> <li>diplomatic good offices, negotiation, mediation, and facilitated dialogue;</li> <li>ceasefire design, monitoring, verification, incident clarification, and implementation support;</li> <li>accompaniment, protective presence, and humanitarian coordination where separately lawful;</li> <li>truth, memory, acknowledgement, apology, reparative dialogue, and reconciliation;</li> <li>return, reintegration, institutional rebuilding, livelihood recovery, and peace dividends;</li> <li>cross-border and interstate peace support;</li> <li>climate, land, resource, labour, digital, spiritual, intercommunal, and institutional conflicts;</li> <li>training, ethics, learning, and practitioner support;</li> <li>interfaces with Justice, Shield, Kintsugi, Migration, Synoptic, Aurora, Indigenous governance, AUBI, Work in Liberation, Treaty bodies, and emergency systems.</li></ul> <h2>2.3 Non-authority clause</h2> <p>This framework does not itself:</p> <ul><li>create a legislature, court, prosecutor, police service, intelligence body, military force, sanctions authority, border authority, detention power, emergency command, or compulsory truth commission;</li> <li>define an offence, enemy, extremist group, terrorist organization, legitimate government, lawful combatant, protected status, or territorial settlement;</li> <li>authorize surveillance, source recruitment, undercover activity, interception, search, seizure, arrest, restraint, detention, deportation, extradition, sanctions, force, weapons, hacking, or armed peace enforcement;</li> <li>authorize a peace body to compel attendance, testimony, disclosure, apology, forgiveness, reconciliation, disarmament, return, relocation, or institutional reform;</li> <li>convert a ceasefire, mediation agreement, community compact, religious declaration, customary process, council vote, or peace forum into law beyond the authority and consent that independently sustain it;</li> <li>override Indigenous jurisdiction, domestic constitutional order, international law, humanitarian law, refugee law, labour rights, disability rights, child rights, survivor sovereignty, or due process;</li> <li>allow a model, metric, facilitator, council, donor, mediator, religious body, or AI system to determine dangerousness, truth, guilt, political legitimacy, or coercive necessity.</li></ul> <h2>2.4 Consequential-action rule</h2> <p>When a proposed action may affect liberty, bodily integrity, privacy, home, communications, property, livelihood, movement, legal status, family unity, political participation, reputation, digital systems, territorial authority, or essential services, the initiating body must classify the action under <code>SCPA/0.1</code> and identify the independently competent authority.</p> <p>A Peace record can describe a concern, request, refusal, consent, agreement, incident, or unresolved dispute. It cannot substitute for an <code>SCPA</code> authority record.</p> <h2>2.5 Voluntary-participation rule</h2> <p>Participation in mediation, dialogue, values exploration, cultural or spiritual practice, truth-telling, reconciliation, community ceremony, restorative process, or peace education is voluntary unless a separately valid legal order requires a narrow procedural act. Refusal or withdrawal must not by itself:</p> <ul><li>reduce access to safety, asylum, housing, income, healthcare, education, legal aid, humanitarian relief, or public services;</li> <li>establish bad faith, dangerousness, guilt, radicalization, developmental deficiency, or unfitness;</li> <li>trigger a security referral, watchlist, sanction, detention, or adverse status decision;</li> <li>disadvantage a party in unrelated justice or administrative proceedings.</li></ul> <h2>2.6 Normative language</h2> <p><strong>MUST</strong> and <strong>SHALL</strong> state conformance conditions. <strong>SHOULD</strong> states a rebuttable design requirement. <strong>MAY</strong> identifies an option. These terms do not create power; they define what an implementation must demonstrate to claim conformity.</p> <hr> <h1>3. Peace-support function map</h1> <p>Peace support is decomposed into separate functions. No body receives all functions merely because it uses the word peace.</p> <table><thead><tr><th>Function</th><th>Primary purpose</th><th>What it may do</th><th>What it may not infer</th></tr></thead><tbody><tr><td>Prevention and civic space</td><td>reduce avoidable escalation</td><td>convene, map conditions, support communication, fund nonviolent infrastructure</td><td>that tension creates security jurisdiction</td></tr><tr><td>Good offices</td><td>enable contact</td><td>transmit messages, propose formats, arrange venues</td><td>that access implies representation</td></tr><tr><td>Mediation and negotiation</td><td>support voluntary agreement</td><td>facilitate, clarify, draft options, record consent</td><td>that agreement proves legal validity beyond its authority</td></tr><tr><td>Ceasefire support</td><td>reduce violence and support compliance</td><td>help define terms, monitor by consent, clarify incidents</td><td>that a reported breach proves guilt or authorizes force</td></tr><tr><td>Humanitarian coordination</td><td>protect access to essential assistance</td><td>coordinate routes, deconfliction, referrals, civilian needs</td><td>that humanitarian access creates intelligence authority</td></tr><tr><td>Truth and memory</td><td>acknowledge harms and preserve accounts</td><td>support testimony, archives, memorialization, apology</td><td>that testimony is automatically criminal evidence</td></tr><tr><td>Reconciliation</td><td>support chosen relational repair</td><td>circles, dialogue, ritual, reparative commitments</td><td>that forgiveness or unity is required</td></tr><tr><td>Reconstruction</td><td>rebuild institutions and material conditions</td><td>coordinate services, livelihoods, land processes, peace dividends</td><td>that funding buys political compliance</td></tr><tr><td>Learning and standards</td><td>improve practice</td><td>training, ethics, comparative learning, evaluation</td><td>that standard-setting creates jurisdiction</td></tr></tbody></table> <hr> <h1>4. Institutional architecture</h1> <h2>4.1 Peace Support Commons</h2> <p>The <strong>Peace Support Commons</strong> is a non-sovereign federation of independently constituted support nodes. It may maintain:</p> <ul><li>voluntary practitioner and institution rosters;</li> <li>accessible request-routing channels;</li> <li>model agreements and process templates;</li> <li>training resources and peer support;</li> <li>protected failure and learning libraries;</li> <li>translation, accessibility, logistics, and technical assistance;</li> <li>optional coordination among invited support providers;</li> <li>compatibility registers for relevant framework versions.</li></ul> <p>The Commons may not:</p> <ul><li>declare a conflict or emergency;</li> <li>designate legitimate parties or representatives;</li> <li>impose a mediator or process;</li> <li>command a peace team;</li> <li>maintain a security watchlist or intelligence dossier;</li> <li>determine criminality, extremism, dangerousness, developmental stage, or spiritual motive;</li> <li>order sanctions, detention, force, border action, or institutional dissolution;</li> <li>distribute reconstruction funding based on ideological compliance, public approval, or participation in peace processes;</li> <li>claim jurisdiction from successful performance.</li></ul> <h2>4.2 Peace Support Nodes</h2> <p>A node may be constituted by an Indigenous nation, municipality, region, state, treaty body, civil-society network, labour organization, faith or non-faith network, university, humanitarian body, or affected community. Its mandate, territory, constituency, funding, selection, conflict-of-interest rules, data obligations, and dissolution procedure must be explicit.</p> <p>A node may not present itself as representative of a population unless that population has validly authorized the representation.</p> <h2>4.3 Request and invitation</h2> <p>Peace support begins through one or more documented routes:</p> <ol><li>joint invitation by parties;</li> <li>invitation by an affected Indigenous nation or competent territorial authority;</li> <li>request by a community, worker body, survivor group, or civil-society actor for a non-coercive service within lawful access boundaries;</li> <li>good-offices offer that remains inactive until accepted;</li> <li>treaty-based diplomatic mandate that identifies scope and limits;</li> <li>court- or authority-referred voluntary mediation, provided refusal does not prejudice substantive rights unless valid law narrowly provides otherwise.</li></ol> <p>Every request must identify who invited the service, whom the requester can and cannot bind, the proposed function, territorial access, language and accessibility needs, data rules, conflicts of interest, and withdrawal route.</p> <h2>4.4 No permanent privileged seat</h2> <p>No religious, spiritual, ideological, developmental, professional, state, donor, or civil-society body receives a permanent seat by this framework. Faith, spiritual, Indigenous, secular, humanist, survivor, youth, disability, labour, and other perspectives may participate when relevant and authorized by the affected parties or constituting instrument.</p> <h2>4.5 Independent oversight</h2> <p>Each implementation must provide independent complaint, ethics, safeguarding, and remedy routes. The body that supplies mediators may not be the sole reviewer of mediator misconduct, data misuse, coercive pressure, retaliation, or unauthorized referral.</p> <hr> <h1>5. Prevention and structural peacebuilding</h1> <h2>5.1 Conditions, not population types</h2> <p>Prevention may assess conditions such as:</p> <ul><li>resource scarcity and unequal access;</li> <li>displacement, land dispossession, housing pressure, or livelihood loss;</li> <li>institutional exclusion or discriminatory practice;</li> <li>unresolved historical harm;</li> <li>labour conflict and economic dependency;</li> <li>environmental degradation and climate pressure;</li> <li>service collapse, corruption, impunity, or legal uncertainty;</li> <li>information-system failures and communication barriers;</li> <li>political exclusion, civic-space contraction, or attacks on association;</li> <li>trauma, fear, rumours, and relationship breakdown as voluntarily reported.</li></ul> <p>It must not classify persons or groups as developmentally inferior, primitive, extremist, irrational, spiritually driven, culturally deficient, or insufficiently integrated.</p> <h2>5.2 Participatory assessment</h2> <p>Structural and relational assessment must be:</p> <ul><li>voluntary and purpose-limited;</li> <li>co-designed with affected people;</li> <li>accessible and multilingual;</li> <li>explicit about who will receive the output;</li> <li>separated from security, immigration, employment, insurance, welfare, and criminal databases;</li> <li>open to correction, dissent, and withdrawal;</li> <li>capable of recording uncertainty and conflicting accounts;</li> <li>prohibited from claiming that a survey score represents a community’s essence or consent.</li></ul> <h2>5.3 Early warning without security fusion</h2> <p>A Peace node may identify observable conditions suggesting that dialogue, humanitarian preparation, or protective attention may be useful. It may publish aggregate, non-targeting warnings or transmit a narrowly defined immediate-danger concern through <code>SCPA-18</code> routing.</p> <p>It may not:</p> <ul><li>build predictive-policing or political-risk profiles;</li> <li>feed mediation, spiritual, trauma, values, or community-dialogue data into a shared intelligence picture;</li> <li>use AI to assign threat, radicalization, violence, credibility, or loyalty scores;</li> <li>nominate individuals or groups for investigation or surveillance based on speech, identity, association, belief, migration status, or refusal to participate;</li> <li>allow a warning model to activate sanctions, enforcement, detention, or force.</li></ul> <h2>5.4 Civic-space support</h2> <p>Prevention may support:</p> <ul><li>safe venues and communication channels;</li> <li>independent media and public-information access under Synoptic v4.2;</li> <li>legal aid and rights education;</li> <li>labour dialogue and collective bargaining;</li> <li>youth and community participation;</li> <li>protection of defenders and whistleblowers through competent mechanisms;</li> <li>accessible public consultation;</li> <li>material interventions addressing housing, food, water, healthcare, education, employment, or environmental stress;</li> <li>community-controlled rumour clarification that does not become propaganda or surveillance.</li></ul> <h2>5.5 Material peacebuilding</h2> <p>Peace funding should prioritize transparent, rights-preserving measures that reduce structural drivers. It must not require ideological alignment, reconciliation, behavioural scoring, surveillance participation, or support for a preferred political settlement.</p> <hr> <h1>6. Values, culture, developmental models, and meaning</h1> <h2>6.1 Optional interpretive tools</h2> <p>Values language, systems maps, narrative analysis, developmental models, cultural concepts, and spiritual vocabularies may be used as optional reflective tools when participants find them useful. They must not be treated as scientific diagnoses, legal categories, population rankings, or universal maps of human maturity.</p> <h2>6.2 Prohibited uses</h2> <p>No implementation may use Spiral Dynamics colours, moral-stage labels, religious-driver percentages, trust thresholds, cohesion scores, psychological profiles, trauma assessments, or cultural categories to:</p> <ul><li>select coercive or security pathways;</li> <li>determine credibility, guilt, consent, capacity, or dangerousness;</li> <li>assign a party to a lesser form of rights or participation;</li> <li>justify honouring a leader who lacks valid authority;</li> <li>decide that a community is ready or unready for democracy, equality, autonomy, or legal protection;</li> <li>condition funds, services, visas, public standing, or institutional legitimacy;</li> <li>prescribe contemplative, religious, or therapeutic practice.</li></ul> <h2>6.3 Participant-controlled language</h2> <p>Facilitators should use the language participants choose for their own values, interests, duties, histories, identities, and aspirations. Imported terms such as Ubuntu, Sulh, Dharma, Samaj, kinship, ceremony, or contemplative unity must not be detached from their communities or used as generic branding without authorization.</p> <h2>6.4 No engineered transformation target</h2> <p>The objective is not to move a population toward a preferred developmental stage. Peace support may help people clarify options, reduce harm, and build workable relationships. Participants retain the right to disagree about worldview, meaning, religion, metaphysics, tradition, modernity, identity, and the good life.</p> <hr> <h1>7. Good offices, dialogue, mediation, and negotiation</h1> <h2>7.1 Good offices</h2> <p>Good offices may establish contact, communicate invitations, arrange safe venues, identify accessibility needs, and propose process options. The provider must not claim to represent a party, guarantee an outcome, or transmit confidential information beyond the authorized purpose.</p> <h2>7.2 Mediation mandate</h2> <p>A mediation mandate must identify:</p> <ul><li>parties and represented constituencies;</li> <li>the mediator’s appointment and removal route;</li> <li>issues included and excluded;</li> <li>legal and territorial context;</li> <li>voluntary-participation rules;</li> <li>confidentiality and disclosure exceptions;</li> <li>data retention and destruction;</li> <li>accessibility, language, disability, child, and survivor safeguards;</li> <li>relationships to legal proceedings;</li> <li>whether any agreement requires ratification, legislation, judicial approval, Indigenous authorization, or public consent;</li> <li>withdrawal, pause, replacement, and termination procedures.</li></ul> <h2>7.3 Informed consent and power asymmetry</h2> <p>Consent must be ongoing and assessed in light of violence, coercive control, detention, displacement, economic dependency, immigration status, child custody, social pressure, armed presence, institutional hierarchy, and fear of retaliation.</p> <p>A mediator must not use procedural neutrality to ignore domination. The response to a severe power imbalance may include separate processes, independent advocates, legal advice, material support, shuttle diplomacy, public-law safeguards, or declining mediation. It is not necessarily to force a face-to-face encounter.</p> <h2>7.4 No justice waiver</h2> <p>Mediation does not waive access to courts, Indigenous legal institutions, labour procedures, asylum, protection, emergency assistance, or administrative review. A settlement cannot validly waive non-waivable rights, bind non-consenting people, legalize abuse, transfer Indigenous authority, conceal ongoing danger, or preclude lawful investigation where law independently requires it.</p> <h2>7.5 Confidentiality and evidentiary separation</h2> <p>Mediation statements, caucus communications, spiritual disclosures, trauma narratives, apologies, exploratory proposals, and unaccepted offers are protected according to the agreed process and applicable law. Any exception for immediate danger, child safeguarding, court order, or mandatory reporting must be narrow, disclosed in advance where possible, and documented under the relevant SCPA route.</p> <p>A Peace body may not promise absolute confidentiality where law does not permit it, nor invent disclosure authority where law does not require it.</p> <h2>7.6 Agreement validity</h2> <p>A signed or cryptographically verified document proves only that a particular record exists and may indicate assent. It does not prove informed consent, authority to bind others, legality, absence of coercion, factual truth, constitutional validity, or implementation capacity.</p> <h2>7.7 Failure and impasse</h2> <p>Impasse may lead to pause, process redesign, mediator replacement, separate tracks, rights advice, humanitarian support, continued nonviolent contact, or closure. It does not automatically lead to Justice, Shield, sanctions, surveillance, detention, or force.</p> <hr> <h1>8. Ceasefire and violence-reduction support</h1> <h2>8.1 Legal character</h2> <p>A ceasefire may be political, humanitarian, military, local, community-based, labour-related, or otherwise bounded. Its legal effect depends on the authority and law that sustain it. Peace v1.8.1 provides design and support tools; it does not create command over armed actors.</p> <h2>8.2 Minimum ceasefire package</h2> <p>A supported ceasefire should identify:</p> <ul><li>parties, signatories, and constituencies;</li> <li>geographic and temporal scope;</li> <li>prohibited and permitted conduct;</li> <li>civilian-protection and humanitarian-access rules;</li> <li>command-notification routes;</li> <li>incident-reporting and clarification procedures;</li> <li>monitoring authority, access, consent, safety, and data limits;</li> <li>treatment of disputed facts;</li> <li>communication and correction rules;</li> <li>complaint and review;</li> <li>termination, renewal, withdrawal, and successor arrangements;</li> <li>relationship to humanitarian law, criminal accountability, and political negotiation.</li></ul> <h2>8.3 Monitoring and verification</h2> <p>Monitoring may use observers, community reports, technical sensors, satellite products, or incident logs only within valid access, consent, data, and safety rules. A monitor records observations and confidence; it does not adjudicate guilt or authorize retaliation.</p> <p>Technical evidence must preserve uncertainty, provenance, limitations, alternative explanations, and chain of custody where later legal use is contemplated.</p> <h2>8.4 No intelligence laundering</h2> <p>A ceasefire-monitoring mission may not covertly collect unrelated political, military, migration, commercial, religious, or community intelligence. Information gathered for incident clarification cannot be repurposed without a valid <code>SCPA-09</code> and <code>SCPA-10</code> route, and where necessary a separate investigation authorization.</p> <h2>8.5 Breach response</h2> <p>A reported breach may trigger clarification, notification, protective advice, humanitarian adjustment, urgent dialogue, or a separately authorized referral. It does not itself authorize force, sanctions, arrest, detention, or attribution to a state or organization.</p> <h2>8.6 Civilian protection and humanitarian access</h2> <p>Peace actors may coordinate deconfliction, evacuation requests, aid access, protective presence, and civilian information. They may not command armed escorts, establish detention sites, screen populations for intelligence purposes, or condition aid on political cooperation.</p> <hr> <h1>9. Immediate danger, atrocity risk, and referral boundaries</h1> <h2>9.1 Immediate danger</h2> <p>When a Peace practitioner reasonably perceives an imminent risk of death, serious bodily harm, disappearance, trafficking, mass violence, or another grave and immediate danger, the practitioner may:</p> <ul><li>provide voluntary assistance within competence;</li> <li>help a person reach safety;</li> <li>contact a lawfully competent urgent-protection body;</li> <li>transmit the minimum necessary information;</li> <li>preserve the person’s choices and confidentiality as far as possible;</li> <li>document the referral as an <code>SCPA-18</code> interface event.</li></ul> <p>The practitioner does not thereby acquire search, arrest, restraint, custody, force, or command authority.</p> <h2>9.2 Atrocity-risk assessment</h2> <p>Atrocity prevention may combine public evidence, community warnings, humanitarian indicators, and specialist analysis. Outputs must state uncertainty and must not become target lists. Any protective or coercive response requires separate law, authority, necessity, proportionality, humanitarian-law review, civilian safeguards, and remedy.</p> <h2>9.3 Peace enforcement</h2> <p>This framework does not authorize peace enforcement, no-fly zones, armed escorts, weapons seizure, compulsory disarmament, military intervention, sanctions, detention, or use of force. A body considering such action must proceed under the separately valid Treaty, security, military, emergency, or domestic legal architecture and <code>SCPA/0.1</code>.</p> <p>Peace practitioners may advise on likely conflict effects and civilian risks, but may not command or legitimize the action merely by participating.</p> <h2>9.4 Referral to Shield</h2> <p>Referral to Shield v2.0.1 is appropriate only where there is a distinct transnational-crime, mutual-legal-assistance, cyber-defence, asset-recovery, or victim-protection function. The referral must:</p> <ul><li>identify the exact requested function;</li> <li>exclude mediation, spiritual, trauma, and protected-dialogue information unless lawful and necessary;</li> <li>avoid target nomination based on identity, belief, association, or refusal to negotiate;</li> <li>preserve survivor and witness choice;</li> <li>receive explicit acceptance or rejection;</li> <li>leave authority with the independently competent body.</li></ul> <h2>9.5 Referral to Justice</h2> <p>A party may seek Justice at any time. Peace support may explain options and assist with access but must not determine admissibility, liability, guilt, remedy, jurisdiction, or appeal. Evidence transfer and adjudicative referral remain separate acts.</p> <h2>9.6 Referral to Kintsugi or Migration</h2> <p>Kintsugi may receive requests for community care, survivor support, unarmed de-escalation, or voluntary restorative processes. Migration may receive requests concerning protection, asylum, reception, family unity, non-refoulement, status, or return. Peace records must not become criminal or immigration enforcement data by default.</p> <hr> <h1>10. Truth, memory, acknowledgement, and reconciliation</h1> <h2>10.1 Plural purposes</h2> <p>Truth and memory processes may serve acknowledgement, historical record, institutional learning, survivor voice, reparations, memorialization, missing-person work, community dialogue, or political transition. These purposes should not be collapsed into one mandatory process.</p> <h2>10.2 Voluntary participation and survivor sovereignty</h2> <p>No survivor or affected person must testify, confront a perpetrator, forgive, reconcile, participate in ceremony, accept apology, disclose trauma, or endorse a public narrative to receive support, reparation, legal remedy, or recognition.</p> <h2>10.3 Relationship to criminal and civil justice</h2> <p>Truth, memory, restorative, and reconciliation processes must clearly state:</p> <ul><li>whether statements are confidential, public, privileged, admissible, or protected;</li> <li>whether immunity, amnesty, sentence mitigation, or reparation consequences exist under valid law;</li> <li>who may access records;</li> <li>how allegations are corrected or contested;</li> <li>how criminal evidence is separated and transferred;</li> <li>how participation affects—or does not affect—legal rights.</li></ul> <p>This framework creates no amnesty, immunity, prosecution, evidentiary privilege, or compulsory testimony power.</p> <h2>10.4 Public narrative restraint</h2> <p>A truth or memory institution may publish documented findings within its mandate. It may not claim exclusive authority over history, identity, morality, national memory, or collective meaning. Dissent, uncertainty, minority accounts, protected knowledge, and unfinished questions must be preserved.</p> <h2>10.5 Religious and spiritual participation</h2> <p>Religious or spiritual actors may support processes when invited. Secular, non-religious, multi-faith, intra-faith, and participant-selected alternatives must be available. No GCRSD or other body leads all truth or reconciliation processes by default.</p> <h2>10.6 Memorial and archival care</h2> <p>Archives must distinguish public records, confidential testimony, sealed evidence, personal data, community-controlled records, Indigenous knowledge, and sacred materials. Return, deletion, restriction, correction, and long-term stewardship rules must be explicit.</p> <hr> <h1>11. Reconstruction, return, and peace dividends</h1> <h2>11.1 Reconstruction is not political payment</h2> <p>Reconstruction finance may support housing, water, energy, healthcare, education, transport, livelihoods, public administration, land restoration, cultural continuity, disability access, psychosocial support, and local economic recovery. It must not be conditioned on ideological conformity, public praise, participation in reconciliation, support for a settlement, security reporting, or developmental transformation.</p> <h2>11.2 Affected-person and worker participation</h2> <p>Reconstruction planning must include displaced people, returnees, host communities, workers, survivors, children and youth, disabled people, affected Indigenous nations, landholders, tenants, informal residents, and groups excluded by prior institutions.</p> <h2>11.3 Return and reintegration</h2> <p>Return must be voluntary, informed, safe, and dignified. Peace actors may support dialogue and planning but cannot determine asylum status, terminate protection, compel return, adjudicate property, or authorize population transfer. Migration v1.1.1 controls mobility and non-refoulement interfaces; Justice v1.4 controls legal claims and remedies.</p> <h2>11.4 Ex-combatant and former-perpetrator reintegration</h2> <p>Reintegration may include demobilization support, education, livelihood, trauma care, community dialogue, and voluntary restorative processes. It must not:</p> <ul><li>replace lawful adjudication where required;</li> <li>coerce confession, ideology change, spirituality, therapy, or forgiveness;</li> <li>condition basic needs on participation;</li> <li>expose survivors to unwanted contact;</li> <li>use developmental-stage programmes as correctional treatment;</li> <li>convert civilian capability programmes into covert armed or intelligence structures.</li></ul> <h2>11.5 Peace dividends</h2> <p>Peace dividends may be funded through valid fiscal instruments. They should support broadly shared public goods and reparative priorities. They may not be calculated from trust, compliance, reduced dissent, spiritual participation, or favourable mediator ratings.</p> <hr> <h1>12. Indigenous authority, land, knowledge, and peace processes</h1> <h2>12.1 Nation-specific authority</h2> <p>An affected Indigenous nation determines its own representatives, legal processes, consent rules, territorial access, knowledge protocols, and relationships to external peace support. No universal Earth Council, Indigenous Data Sovereignty Council, elder council, or global proxy may consent on its behalf.</p> <h2>12.2 No generic FPIC threshold</h2> <p>Free, prior, and informed consent cannot be reduced to a universal 80% vote or checklist. The relevant nation defines the valid process according to its own law and institutions.</p> <h2>12.3 Land and sacred-site disputes</h2> <p>Peace support may facilitate dialogue but cannot transfer land, waive title, authorize access, determine sacred status, or settle jurisdiction without valid affected-nation and legal authority.</p> <h2>12.4 Protected knowledge</h2> <p>Sacred, ceremonial, ecological, linguistic, genealogical, and other protected knowledge may remain undisclosed, non-digitized, locally held, non-transferable, or represented through limited attestation. Participation in peace processes does not imply consent to archive, publish, train AI, commercialize, or circulate such knowledge.</p> <h2>12.5 External intervention</h2> <p>Urgent action affecting Indigenous territory must follow applicable law, affected-nation emergency interfaces, and SCPA safeguards. A claim of peace, humanitarian need, or atrocity prevention does not erase Indigenous authority.</p> <hr> <h1>13. Faith, spirituality, conscience, and secular equality</h1> <h2>13.1 Invitation, not assignment</h2> <p>Faith and spiritual actors may contribute when invited by relevant participants. A percentage score of spiritual influence cannot trigger referral. Individuals and groups may decline religious framing without losing access to peace support.</p> <h2>13.2 Conscience safeguards</h2> <p>No process may compel prayer, ritual, confession, spiritual counselling, contemplative practice, theological dialogue, or recognition of religious authority. Participants may request secular, multi-faith, intra-faith, Indigenous, humanist, or other appropriate facilitators.</p> <h2>13.3 Internal religious disputes</h2> <p>External facilitators must not determine doctrine, legitimate clergy, orthodoxy, succession, or sacred meaning. They may support a procedure accepted by the relevant participants and lawful institutions.</p> <h2>13.4 Spiritual disclosure firewall</h2> <p>Spiritual counselling, confession, ritual, and pastoral communication must not become intelligence or legal evidence except under independently valid, narrowly defined law and protections. Peace institutions must state any limits before disclosure where possible.</p> <hr> <h1>14. Data, confidentiality, and information firewalls</h1> <h2>14.1 Data minimization</h2> <p>Peace processes should collect the least information necessary. Every record must have a purpose, steward, access class, retention period, correction route, and disposition rule.</p> <h2>14.2 Functional separation</h2> <p>The following data stores must remain functionally separated unless a lawful, necessary, and documented handoff occurs:</p> <ul><li>process administration;</li> <li>confidential mediation communications;</li> <li>participant safety plans;</li> <li>public agreements;</li> <li>ceasefire observations;</li> <li>humanitarian coordination;</li> <li>truth and memory archives;</li> <li>legal evidence;</li> <li>practitioner supervision;</li> <li>aggregate evaluation;</li> <li>complaints and safeguarding;</li> <li>security or intelligence systems.</li></ul> <h2>14.3 Protected mediation and care data</h2> <p>Mediation, Kintsugi, Migration, health, trauma, spiritual, labour, asylum, survivor, child, and Indigenous records are not general-purpose security data. A request for them must identify legal basis, necessity, scope, minimization, protected status, challenge, and disposition under SCPA.</p> <h2>14.4 Public communication</h2> <p>Public communication must distinguish verified facts, party claims, mediator observations, uncertainty, correction, and opinion. Peace bodies may communicate process status and safety information but may not conduct propaganda, psychological operations, reputation management for parties, or engineered persuasion.</p> <h2>14.5 Corrections and contested accounts</h2> <p>Affected persons must have routes to correct administrative facts, record dissent, challenge attribution, and request restriction or deletion where appropriate. Correction does not require accepting a preferred political narrative.</p> <hr> <h1>15. Technology and AI</h1> <h2>15.1 Tool, not authority</h2> <p>Technology may support translation, accessibility, secure communication, scheduling, document comparison, scenario exploration, public information, or aggregate analysis. It may not replace human consent, representation, mediation judgment, legal advice, or authority.</p> <h2>15.2 Prohibited automated uses</h2> <p>No AI system may make or recommend binding decisions about:</p> <ul><li>dangerousness, radicalization, extremism, credibility, guilt, or intent;</li> <li>developmental stage, spiritual motive, cultural fit, or trauma readiness;</li> <li>mediator neutrality or party good faith;</li> <li>ceasefire responsibility;</li> <li>eligibility for safety, aid, asylum, funding, representation, or participation;</li> <li>referral to investigation, detention, sanctions, immigration enforcement, or armed response.</li></ul> <h2>15.3 Optional technology and low-tech equivalence</h2> <p>No blockchain, quantum system, biometric identity, virtual-reality platform, digital credential, or centralized dashboard is mandatory. Paper, in-person, radio, telephone, community messenger, and offline systems must remain viable where appropriate.</p> <h2>15.4 Security and data governance</h2> <p>Systems must follow Aurora v1.3 and Technology Governance v3.6. Security controls must not become identity surveillance, mandatory disclosure, or exclusion from peace support.</p> <h2>15.5 AI training and model use</h2> <p>Peace-process data must not be used to train general AI, behavioural prediction, emotion recognition, persuasion, or security models without specific lawful authority and valid consent where required. Protected Indigenous, survivor, child, asylum, spiritual, and mediation data are presumptively excluded.</p> <hr> <h1>16. Practitioner ethics, labour, safety, and accountability</h1> <h2>16.1 Role clarity</h2> <p>Practitioners must know whether they are acting as mediators, negotiators, monitors, humanitarian coordinators, legal professionals, therapists, spiritual advisers, researchers, interpreters, security personnel, or public officials. One person may hold multiple qualifications but must not blur roles within a process.</p> <h2>16.2 Competence and humility</h2> <p>Training should include:</p> <ul><li>mediation and negotiation;</li> <li>power asymmetry and coercive control;</li> <li>survivor sovereignty;</li> <li>disability and neurodiversity access;</li> <li>child safeguarding;</li> <li>Indigenous authority and knowledge protection;</li> <li>migration and non-refoulement boundaries;</li> <li>humanitarian principles;</li> <li>data protection and SCPA firewalls;</li> <li>trauma sensitivity without amateur diagnosis;</li> <li>interpreter ethics;</li> <li>digital and cyber literacy;</li> <li>conflict-of-interest and recusal;</li> <li>practitioner limits and safe referral.</li></ul> <p>No universal hour count or spiritual curriculum proves competence.</p> <h2>16.3 Labour rights</h2> <p>Peace workers must receive wages, contracts, insurance, rest, safe accommodation, psychosocial support, collective representation, whistleblower protection, and safe refusal. Hearts, honour, spiritual status, or public praise cannot replace pay.</p> <h2>16.4 Safety and stop-work</h2> <p>Practitioners may pause or withdraw where safety, consent, role integrity, confidentiality, or legality cannot be maintained. Stop-work does not authorize abandonment without a continuity and handoff plan where vulnerable people depend on the service.</p> <h2>16.5 Misconduct</h2> <p>Sexual exploitation, coercion, retaliation, data misuse, political manipulation, spiritual abuse, discrimination, concealed conflicts, unauthorized security referral, and misrepresentation of authority require independent complaint and remedy routes.</p> <hr> <h1>17. Financing and material independence</h1> <h2>17.1 Valid sources</h2> <p>Peace support may be financed through public appropriations, treaty instruments, foundations, voluntary contributions, pooled funds, reparations, or other lawful sources. The framework itself creates no tax, sanction, levy, asset-recovery entitlement, or mandatory state contribution.</p> <h2>17.2 Donor non-control</h2> <p>Funding agreements must disclose interests and prohibit donors from selecting political outcomes, parties, mediators, target populations, narratives, referrals, or evaluation findings.</p> <h2>17.3 No coercive incentives</h2> <p>Access to trade, public services, humanitarian aid, AUBI Layer 1, asylum, justice, essential reconstruction, or safety may not be conditioned on signing a peace agreement, joining a dialogue, accepting a spiritual process, or receiving a favourable “peace score.”</p> <h2>17.4 Community and practitioner continuity</h2> <p>When a programme closes, services, records, assets, worker obligations, participant safety plans, archives, and unresolved duties must be handed back or transferred through a documented continuity plan.</p> <hr> <h1>18. Measurement, learning, and anti-Goodhart safeguards</h1> <h2>18.1 Permissible evaluation dimensions</h2> <p>Evaluation may examine:</p> <ul><li>access, language, disability, and representation;</li> <li>participant-reported safety and agency;</li> <li>procedural fairness and ability to withdraw;</li> <li>implementation of agreements;</li> <li>durability of communication channels;</li> <li>reduction in specified incidents, with attribution caution;</li> <li>material reconstruction and service restoration;</li> <li>worker safety and retention;</li> <li>data compliance and correction;</li> <li>complaints, failures, reversals, and unintended harm;</li> <li>the proportion of cases where non-intervention or closure was correct.</li></ul> <h2>18.2 Prohibited targets</h2> <p>Implementations must not optimize for:</p> <ul><li>trust in the framework or institution;</li> <li>ideological, spiritual, or developmental transformation;</li> <li>reconciliation, forgiveness, apology, or unity rates;</li> <li>number of security referrals, arrests, sanctions, or intelligence reports;</li> <li>agreement signatures without quality and authority assessment;</li> <li>low reporting of violence or complaints;</li> <li>community compliance, reduced dissent, or approval of leadership;</li> <li>mandatory mediator approval thresholds;</li> <li>expansion of institutional jurisdiction.</li></ul> <h2>18.3 Failure library</h2> <p>A protected learning system should document failed assumptions, inappropriate interventions, harmful referrals, coerced settlements, power asymmetries, data breaches, false warnings, exclusion, and cases where peace support should not have intervened. Publication must protect people and confidential processes.</p> <h2>18.4 No causal overclaim</h2> <p>Conflict outcomes are multi-causal. Reports must distinguish observation, participant interpretation, plausible contribution, and demonstrated causal effect. Numerical improvements must not be attributed to Peace without a defensible method.</p> <hr> <h1>19. Cross-framework interface rules</h1> <h2>19.1 Justice Systems v1.4</h2> <p>Peace may support voluntary settlement, restorative options, communication, and implementation. Justice independently controls law, jurisdiction, standing, evidence, warrants, adjudication, appeal, and remedy. Mediation is not a mandatory gate unless valid law provides a rights-preserving route.</p> <h2>19.2 Shield v2.0.1</h2> <p>Shield may receive narrowly defined referrals for transnational crime cooperation, mutual legal assistance, cyber defence, asset recovery, or victim protection. Peace data remains protected. Shield does not inherit mediator access, trust, representation, or territorial entry.</p> <h2>19.3 Kintsugi v2.2.1</h2> <p>Kintsugi receives care, survivor, de-escalation, sanctuary, and voluntary restorative requests. Peace processes do not activate an urgent protective response function. Immediate danger follows <code>SCPA-18</code>.</p> <h2>19.4 Migration v1.1.1</h2> <p>Migration controls asylum, protection, reception, non-refoulement, status, family unity, return, and relocation interfaces. Participation in peacebuilding cannot determine immigration status, credibility, detention, or removal.</p> <h2>19.5 Aurora v1.3 and Synoptic v4.2</h2> <p>Aurora governs data rights, consent, purpose limitation, access, correction, and disposition. Synoptic governs public-information conditions without determining official truth or authorizing counterpropaganda. Peace bodies may not become epistemic police.</p> <h2>19.6 Indigenous Sovereignty v1.1</h2> <p>Affected nations retain their own authority. A generic Indigenous representative, cultural mediator, or global council cannot waive nation-specific jurisdiction or consent.</p> <h2>19.7 Treaty and emergency systems</h2> <p>Treaty and emergency bodies may provide separately constituted diplomatic, humanitarian, protective, or enforcement authority. Peace participation does not validate that authority, and severity does not create jurisdiction.</p> <h2>19.8 Aegis</h2> <p>Aegis-converted capabilities may support civilian transport, communication, engineering, or logistics under their civilian mission charters. Any proposed use for surveillance, targeting, intelligence, detention, border control, crowd control, raids, weapons, offensive cyber action, or armed protection triggers security-use reversion and <code>SCPA/0.1</code>.</p> <hr> <h1>20. Operational lifecycle</h1> <p>A Peace engagement follows the following lifecycle:</p> <ol><li><strong>request or offer</strong>;</li> <li><strong>standing and invitation verification</strong>;</li> <li><strong>conflict-of-interest and safeguarding review</strong>;</li> <li><strong>function classification</strong>;</li> <li><strong>mandate and data agreement</strong>;</li> <li><strong>participant preparation and access support</strong>;</li> <li><strong>operation</strong>;</li> <li><strong>continuous consent, safety, and scope review</strong>;</li> <li><strong>agreement, impasse, referral, pause, or closure</strong>;</li> <li><strong>implementation support where authorized</strong>;</li> <li><strong>record disposition and authority return</strong>;</li> <li><strong>independent complaint, remedy, and learning</strong>.</li></ol> <p>No stage automatically activates the next. Referral acceptance must be explicit.</p> <hr> <h1>21. Peace operational records</h1> <p>The following records form the minimum Peace v1.8.1 operational profile. A jurisdiction may split or extend them but may not omit an applicable safeguard merely by renaming the record.</p> <table><thead><tr><th>ID</th><th>Record</th><th>Minimum purpose</th></tr></thead><tbody><tr><td><code>PCR-01</code></td><td>Peace Support Request or Invitation Record</td><td>requester, represented constituency, function requested, territorial access, withdrawal</td></tr><tr><td><code>PCR-02</code></td><td>Standing, Representation, and Constituency Record</td><td>who may speak, negotiate, observe, or bind; contested representation</td></tr><tr><td><code>PCR-03</code></td><td>Peace Function Classification Record</td><td>prevention, good offices, mediation, ceasefire, truth, reconstruction, referral</td></tr><tr><td><code>PCR-04</code></td><td>Mandate, Scope, and Excluded-Powers Record</td><td>issues, duration, law, authority, exclusions, amendment</td></tr><tr><td><code>PCR-05</code></td><td>Consent, Withdrawal, and Power-Imbalance Record</td><td>ongoing consent, coercive dependencies, separate-process needs</td></tr><tr><td><code>PCR-06</code></td><td>Rights, Accessibility, Language, and Participation Plan</td><td>disability, interpretation, child, survivor, remote and low-tech access</td></tr><tr><td><code>PCR-07</code></td><td>Mediator or Facilitator Appointment and Conflict Record</td><td>selection, disclosure, recusal, replacement, removal</td></tr><tr><td><code>PCR-08</code></td><td>Data Purpose, Access, Retention, and Disposition Record</td><td>purpose limitation, stewards, access classes, correction, deletion</td></tr><tr><td><code>PCR-09</code></td><td>Confidentiality, Privilege, and Disclosure-Limits Record</td><td>protected communications and lawful exceptions</td></tr><tr><td><code>PCR-10</code></td><td>Structural Conditions and Community Account Record</td><td>plural accounts, uncertainty, dissent, no population typing</td></tr><tr><td><code>PCR-11</code></td><td>Preventive Support and Civic-Space Plan</td><td>requested support, material measures, non-security boundaries</td></tr><tr><td><code>PCR-12</code></td><td>Good Offices Contact and Message-Authority Record</td><td>authorized communication, non-representation, source protection</td></tr><tr><td><code>PCR-13</code></td><td>Mediation Process Design Record</td><td>format, issues, sequencing, caucus, legal advice, accessibility</td></tr><tr><td><code>PCR-14</code></td><td>Proposal, Option, and Non-Agreement Record</td><td>exploratory status, no inference of assent or guilt</td></tr><tr><td><code>PCR-15</code></td><td>Agreement, Ratification, and Implementation Authority Record</td><td>signatures, authority, required approvals, non-party effects</td></tr><tr><td><code>PCR-16</code></td><td>Impasse, Pause, Redesign, or Closure Record</td><td>reason, options, no coercive inference, continuity</td></tr><tr><td><code>PCR-17</code></td><td>Ceasefire Mandate and Terms Record</td><td>parties, scope, conduct, duration, humanitarian rules</td></tr><tr><td><code>PCR-18</code></td><td>Ceasefire Monitoring Access and Method Record</td><td>observer authority, sensors, limits, safety, data</td></tr><tr><td><code>PCR-19</code></td><td>Ceasefire Incident Observation and Uncertainty Record</td><td>observation, provenance, confidence, disputed attribution</td></tr><tr><td><code>PCR-20</code></td><td>Humanitarian Access and Deconfliction Record</td><td>routes, contacts, civilian safeguards, intelligence exclusion</td></tr><tr><td><code>PCR-21</code></td><td>Immediate-Danger Referral Record</td><td>minimum necessary facts, SCPA-18 route, consent where possible</td></tr><tr><td><code>PCR-22</code></td><td>Cross-Framework Referral and Acceptance Record</td><td>exact function, protected exclusions, acceptance/rejection</td></tr><tr><td><code>PCR-23</code></td><td>Truth, Memory, or Acknowledgement Mandate Record</td><td>purpose, participation, public/private status, legal relationship</td></tr><tr><td><code>PCR-24</code></td><td>Testimony, Narrative, and Protected-Account Record</td><td>consent, access, correction, admissibility limits, withdrawal</td></tr><tr><td><code>PCR-25</code></td><td>Reconciliation and Process-Choice Record</td><td>voluntary pathways, no forgiveness requirement, survivor safeguards</td></tr><tr><td><code>PCR-26</code></td><td>Archive, Memorial, and Knowledge-Stewardship Record</td><td>custody, access, sacred materials, return, long-term care</td></tr><tr><td><code>PCR-27</code></td><td>Reconstruction and Peace-Dividend Authority Record</td><td>legal funding, allocation, non-conditioning, affected-person participation</td></tr><tr><td><code>PCR-28</code></td><td>Return, Reintegration, and Non-Refoulement Interface Record</td><td>voluntary return, Migration handoff, safety and rights</td></tr><tr><td><code>PCR-29</code></td><td>Indigenous Affected-Nation Interface Record</td><td>nation-specific authority, territory, knowledge, consent</td></tr><tr><td><code>PCR-30</code></td><td>Faith, Spiritual, Conscience, and Secular-Option Record</td><td>invitation, opt-out, confidentiality, no doctrinal authority</td></tr><tr><td><code>PCR-31</code></td><td>Public Communication, Correction, and Non-Propaganda Record</td><td>fact/claim distinction, uncertainty, corrections, prohibited persuasion</td></tr><tr><td><code>PCR-32</code></td><td>Practitioner Role, Labour, Safety, and Stop-Work Record</td><td>role, competence, pay, insurance, support, safe refusal</td></tr><tr><td><code>PCR-33</code></td><td>Complaint, Safeguarding, and Independent Review Record</td><td>misconduct, retaliation, accessibility, external review</td></tr><tr><td><code>PCR-34</code></td><td>Programme Termination, Continuity, and Authority Return Record</td><td>service handback, assets, duties, unresolved risks</td></tr><tr><td><code>PCR-35</code></td><td>Evaluation, Failure, and Non-Intervention Learning Record</td><td>methods, uncertainty, harms, correct non-escalation</td></tr></tbody></table> <p>Each record must identify the relevant <code>cluster_event_id</code>, engagement identifier, version pins, record steward, access class, created and updated times, correction history, applicable law, linked records, status, and closure condition where relevant.</p> <hr> <h1>22. SCPA conformance profile</h1> <p>Peace is primarily an Action Class A framework. The following table states how each <code>SCPA/0.1</code> record applies. <code>imports</code> means the canonical SCPA record is used directly when the corresponding consequential action occurs. <code>interfaces</code> means a Peace record may initiate or link the route but cannot complete it. <code>not normally applicable</code> means the record is absent from ordinary Peace work and becomes mandatory if an implementation crosses that boundary.</p> <table><thead><tr><th>SCPA</th><th>Canonical record</th><th>Peace v1.8.1 relationship</th></tr></thead><tbody><tr><td><code>SCPA-01</code></td><td>Protective or Coercive Action Authority Provenance Record</td><td>imports for any consequential referral or action</td></tr><tr><td><code>SCPA-02</code></td><td>Standing, Jurisdiction, and Territorial Basis Map</td><td>extends through PCR-02 and PCR-04; imports for consequential action</td></tr><tr><td><code>SCPA-03</code></td><td>Action Classification and Procedural Route Record</td><td>extends through PCR-03 and PCR-22</td></tr><tr><td><code>SCPA-04</code></td><td>Individualized Factual Basis and Attribution Record</td><td>not normally applicable; mandatory before individual consequence</td></tr><tr><td><code>SCPA-05</code></td><td>Prohibited Inference and Automated-Use Record</td><td>implements through §§6, 14, and 15</td></tr><tr><td><code>SCPA-06</code></td><td>Necessity, Proportionality, and Alternatives Record</td><td>imports for urgent or coercive action</td></tr><tr><td><code>SCPA-07</code></td><td>Rights, Accessibility, and Protected-Status Safeguards Record</td><td>extends through PCR-06</td></tr><tr><td><code>SCPA-08</code></td><td>Notice, Reasons, Counsel, Interpretation, and Challenge Record</td><td>imports when legal consequence is proposed</td></tr><tr><td><code>SCPA-09</code></td><td>Protected Information or Source Intake Record</td><td>interfaces through PCR-09, PCR-21, PCR-22, and PCR-24</td></tr><tr><td><code>SCPA-10</code></td><td>Intelligence Purpose, Minimization, and Dissemination Record</td><td>not a Peace power; imports before any intelligence use</td></tr><tr><td><code>SCPA-11</code></td><td>Investigation Opening and Mandate Record</td><td>not a Peace power; imports before investigation</td></tr><tr><td><code>SCPA-12</code></td><td>Investigation Method, Scope, and Minimization Record</td><td>not a Peace power; imports before investigative method</td></tr><tr><td><code>SCPA-13</code></td><td>Compulsory Process Application Record</td><td>not a Peace power; imports before compulsion</td></tr><tr><td><code>SCPA-14</code></td><td>Search, Entry, Inspection, or Access Authorization Record</td><td>not a Peace power; imports before search or entry</td></tr><tr><td><code>SCPA-15</code></td><td>Disclosure, Production, Preservation, or Interception Order Record</td><td>imports before compulsory disclosure or interception</td></tr><tr><td><code>SCPA-16</code></td><td>Evidence Seizure, Copying, and Chain-of-Custody Record</td><td>interfaces only through separately authorized evidence transfer</td></tr><tr><td><code>SCPA-17</code></td><td>Asset Preservation, Freeze, Restraint, or Seizure Record</td><td>not a Peace power; imports before asset action</td></tr><tr><td><code>SCPA-18</code></td><td>Urgent Protective Action Record</td><td>interfaces through PCR-21; receiving authority completes</td></tr><tr><td><code>SCPA-19</code></td><td>Arrest or Physical Restraint Record</td><td>not a Peace power; imports before restraint</td></tr><tr><td><code>SCPA-20</code></td><td>Custody or Detention Authority and Welfare Record</td><td>not a Peace power; imports before custody</td></tr><tr><td><code>SCPA-21</code></td><td>Release, Bail, Supervision, or Less-Restrictive Alternative Record</td><td>imports where custody exists</td></tr><tr><td><code>SCPA-22</code></td><td>Transfer, Extradition, Removal, or Return Authority Record</td><td>interfaces through PCR-28; Migration/Justice controls</td></tr><tr><td><code>SCPA-23</code></td><td>Use-of-Force Incident and Necessity Record</td><td>not a Peace power; imports for any force</td></tr><tr><td><code>SCPA-24</code></td><td>Weapons, Restraint Device, and Special Equipment Authorization Record</td><td>not a Peace power; imports before equipment use</td></tr><tr><td><code>SCPA-25</code></td><td>Mission Command, Technical Command, Custody, and Stop-Work Record</td><td>imports for protected missions or converted assets</td></tr><tr><td><code>SCPA-26</code></td><td>Defensive Cyber Action Record</td><td>not a Peace power; imports for defensive cyber action</td></tr><tr><td><code>SCPA-27</code></td><td>Third-Party Cyber Access, Disruption, or Counter-Operation Record</td><td>not a Peace power; imports before third-party disruption</td></tr><tr><td><code>SCPA-28</code></td><td>Financial Coercion, Sanction, Freeze, Forfeiture, or Exclusion Record</td><td>not a Peace power; imports before financial coercion</td></tr><tr><td><code>SCPA-29</code></td><td>Cross-Border Cooperation and Mutual Legal Assistance Record</td><td>imports for legal/security cooperation; diplomatic peace support uses PCR-04</td></tr><tr><td><code>SCPA-30</code></td><td>Asylum, Protection, Non-Refoulement, and Security-Allegation Record</td><td>interfaces through PCR-28; Migration controls</td></tr><tr><td><code>SCPA-31</code></td><td>Independent Authorization, Adjudication, or Review Record</td><td>imports for any legal determination</td></tr><tr><td><code>SCPA-32</code></td><td>Appeal, Complaint, Urgent Challenge, and Interim Relief Record</td><td>extends through PCR-33; imports for legal challenge</td></tr><tr><td><code>SCPA-33</code></td><td>Remedy, Restitution, Property Return, and Compensation Record</td><td>interfaces with Justice; reconstruction is not substitute</td></tr><tr><td><code>SCPA-34</code></td><td>Restorative, Rehabilitation, Correctional, or Reintegration Consent and Suitability Record</td><td>extends through PCR-25 and PCR-28</td></tr><tr><td><code>SCPA-35</code></td><td>Security Data Disposition, Correction, Expungement, and Use-Limitation Record</td><td>imports after any security referral; PCR-08 governs Peace data</td></tr><tr><td><code>SCPA-36</code></td><td>Action Termination, Authority Return, and Unresolved-Risk Custody Record</td><td>extends through PCR-34</td></tr><tr><td><code>SCPA-37</code></td><td>Identity, Credential, and Service-Access Function Separation Record</td><td>implements non-conditioning and data separation</td></tr><tr><td><code>SCPA-38</code></td><td>Child, Dependent Person, Guardianship, and Best-Interests Record</td><td>imports when children or dependent persons are affected</td></tr><tr><td><code>SCPA-39</code></td><td>Indigenous Territory, Authority, Knowledge, and Affected-Nation Interface Record</td><td>extends through PCR-29</td></tr><tr><td><code>SCPA-40</code></td><td>Survivor Safety, Confidentiality, and Process Choice Record</td><td>extends through PCR-05, PCR-09, PCR-21, PCR-24, PCR-25</td></tr><tr><td><code>SCPA-41</code></td><td>Worker, Operator, Responder, and Whistleblower Protection Record</td><td>extends through PCR-32 and PCR-33</td></tr><tr><td><code>SCPA-42</code></td><td>Public Communication, Classification, Correction, and Non-Propaganda Record</td><td>extends through PCR-31</td></tr><tr><td><code>SCPA-43</code></td><td>Security Institution Transfer, Succession, or Dissolution Continuity Plan</td><td>imports for security bodies; PCR-34 covers Peace programmes</td></tr><tr><td><code>SCPA-44</code></td><td>Coercive-Power Non-Activation and Security-Use Reversion Register</td><td>implements as a standing Peace non-activation rule</td></tr></tbody></table> <hr> <h1>23. Constitutional readiness gates</h1> <p>An implementation may claim Peace v1.8.1 conformity only if all applicable gates pass.</p> <table><thead><tr><th>Gate</th><th>Name</th><th>Pass condition</th></tr></thead><tbody><tr><td><code>G1</code></td><td>Non-authority</td><td>The implementation does not create intelligence, police, military, sanctions, border, detention, adjudicative, or enforcement power.</td></tr><tr><td><code>G2</code></td><td>Invitation and standing</td><td>Each engagement has a valid request, invitation, or mandate and a documented representation boundary.</td></tr><tr><td><code>G3</code></td><td>Voluntary participation</td><td>Participants can refuse or withdraw without unrelated rights or service penalties.</td></tr><tr><td><code>G4</code></td><td>No population typing</td><td>No developmental, spiritual, cultural, psychological, or ideological label creates operational consequences.</td></tr><tr><td><code>G5</code></td><td>Peace–intelligence firewall</td><td>Mediation, spiritual, trauma, values, and dialogue data do not enter intelligence systems by default.</td></tr><tr><td><code>G6</code></td><td>No automatic escalation</td><td>Impasse, breach, tension, or warning never automatically activates coercion.</td></tr><tr><td><code>G7</code></td><td>Power asymmetry</td><td>Coercion, dependency, detention, displacement, and survivor safety are addressed before relational processes.</td></tr><tr><td><code>G8</code></td><td>Justice separation</td><td>Mediation does not adjudicate law, guilt, evidence, liability, appeal, or remedy.</td></tr><tr><td><code>G9</code></td><td>Ceasefire limits</td><td>Monitoring records observation and uncertainty without becoming command, intelligence, or retaliation authority.</td></tr><tr><td><code>G10</code></td><td>Immediate-danger routing</td><td>Urgent protection uses SCPA-18 and minimal necessary information.</td></tr><tr><td><code>G11</code></td><td>Survivor sovereignty</td><td>Support is independent of testimony, forgiveness, reconciliation, or prosecution.</td></tr><tr><td><code>G12</code></td><td>Child safeguards</td><td>Children and dependent persons receive best-interests, guardian, accessibility, and confidentiality protections.</td></tr><tr><td><code>G13</code></td><td>Indigenous authority</td><td>Affected nations determine their own representatives, law, territory, knowledge, and consent.</td></tr><tr><td><code>G14</code></td><td>Conscience equality</td><td>Religious or spiritual participation is invited, optional, and matched by secular alternatives.</td></tr><tr><td><code>G15</code></td><td>Data minimization</td><td>Every data set has purpose, access, retention, correction, and disposition rules.</td></tr><tr><td><code>G16</code></td><td>No automated coercive inference</td><td>AI does not determine dangerousness, referral, credibility, eligibility, or legitimacy.</td></tr><tr><td><code>G17</code></td><td>Public-information integrity</td><td>Communications distinguish fact, claim, uncertainty, correction, and opinion without propaganda.</td></tr><tr><td><code>G18</code></td><td>No coercive finance</td><td>Aid, AUBI, asylum, services, and reconstruction are not conditioned on peace-process participation.</td></tr><tr><td><code>G19</code></td><td>Worker rights</td><td>Practitioners have pay, safety, insurance, support, collective rights, and safe refusal.</td></tr><tr><td><code>G20</code></td><td>Complaint and remedy</td><td>Independent complaint, safeguarding, correction, and remedy routes exist.</td></tr><tr><td><code>G21</code></td><td>Termination and handback</td><td>Mandates, assets, data, unresolved duties, and authority return are explicit.</td></tr><tr><td><code>G22</code></td><td>Version compatibility</td><td>All controlling framework versions are pinned and later substitutions fail closed.</td></tr><tr><td><code>G23</code></td><td>Genesis boundaries</td><td>Pilots test voluntary peace support, not coercive powers, population scoring, or surveillance.</td></tr><tr><td><code>G24</code></td><td>Legitimate non-intervention</td><td>The system can conclude that no intervention, no referral, or closure is the correct outcome.</td></tr></tbody></table> <hr> <h1>24. Compound implementation tests</h1> <p>The following tests are mandatory before controlled adoption. A pass may include a justified decision not to intervene.</p> <table><thead><tr><th>Test</th><th>Scenario</th><th>Required result</th></tr></thead><tbody><tr><td><code>T1</code></td><td>A community requests water-dispute mediation but rejects values-stage classification.</td><td>Support proceeds without developmental labels or reduced service.</td></tr><tr><td><code>T2</code></td><td>A mediator learns of vague political anger but no immediate danger.</td><td>No Shield or intelligence referral occurs.</td></tr><tr><td><code>T3</code></td><td>A participant discloses an imminent plan to kill a named person.</td><td>Minimum necessary SCPA-18 referral occurs; the mediator acquires no force authority.</td></tr><tr><td><code>T4</code></td><td>A faith leader requests mandatory referral because a conflict is “70% spiritual.”</td><td>The numerical trigger is rejected; parties choose facilitators and secular options.</td></tr><tr><td><code>T5</code></td><td>Mediation fails after 30 days.</td><td>The process may pause or close; no automatic escalation occurs.</td></tr><tr><td><code>T6</code></td><td>A ceasefire monitor records an explosion with uncertain origin.</td><td>The record preserves uncertainty and does not authorize retaliation.</td></tr><tr><td><code>T7</code></td><td>A military actor asks ceasefire monitors for unrelated political contacts.</td><td>The request is refused or routed through valid intelligence law.</td></tr><tr><td><code>T8</code></td><td>A survivor wants material support but no truth commission testimony.</td><td>Support continues without penalty.</td></tr><tr><td><code>T9</code></td><td>A restorative process produces an apology that investigators request.</td><td>Protected status is assessed; no silent evidence transfer occurs.</td></tr><tr><td><code>T10</code></td><td>An Indigenous nation declines an external peace team.</td><td>No entry occurs; no global proxy overrides the refusal.</td></tr><tr><td><code>T11</code></td><td>Two factions sign an agreement but lack authority to bind displaced communities.</td><td>The agreement records its limited effect and cannot bind non-parties.</td></tr><tr><td><code>T12</code></td><td>A donor offers reconstruction funding only if parties endorse a preferred constitution.</td><td>The condition is rejected as coercive political financing.</td></tr><tr><td><code>T13</code></td><td>A government demands mediator notes for immigration screening.</td><td>The Peace–Migration firewall blocks default transfer.</td></tr><tr><td><code>T14</code></td><td>A child participates in a family reconciliation process.</td><td>Best-interests, guardian, consent, and confidentiality safeguards apply.</td></tr><tr><td><code>T15</code></td><td>A secular participant refuses a reconciliation ritual.</td><td>An equivalent non-religious process is available without penalty.</td></tr><tr><td><code>T16</code></td><td>An AI tool assigns one group a high radicalization score.</td><td>The score has no operational effect and the tool is removed from the process.</td></tr><tr><td><code>T17</code></td><td>A ceasefire breach may constitute a war crime.</td><td>Observation and evidence routes are separated; Justice independently assesses.</td></tr><tr><td><code>T18</code></td><td>A Peace node is asked to coordinate sanctions to force negotiation.</td><td>It refuses; any sanctions require SCPA-28 and separate authority.</td></tr><tr><td><code>T19</code></td><td>Aegis-converted drones are offered for crowd monitoring near talks.</td><td>Security-use reversion is triggered; no Peace deployment occurs.</td></tr><tr><td><code>T20</code></td><td>A truth commission publishes a contested historical conclusion.</td><td>Dissent, sources, uncertainty, correction, and archive access are preserved.</td></tr><tr><td><code>T21</code></td><td>A community has low survey trust but no active conflict.</td><td>No intervention is triggered solely by the score.</td></tr><tr><td><code>T22</code></td><td>A mediator faces threats from a party.</td><td>Worker safety and stop-work activate without transferring command to Peace.</td></tr><tr><td><code>T23</code></td><td>A programme closes while confidential archives and survivor support remain.</td><td>Continuity, custody, disposition, and handback plans execute.</td></tr><tr><td><code>T24</code></td><td>A later Shield or SCPA version changes data-transfer semantics.</td><td>Compatibility review is required; substitution fails closed.</td></tr><tr><td><code>T25</code></td><td>A party requests a mediator who also serves as an intelligence adviser.</td><td>Conflict is disclosed and the person recuses from one role.</td></tr><tr><td><code>T26</code></td><td>A public rumour threatens humanitarian access.</td><td>Peace may issue corrected process information without propaganda or target profiling.</td></tr><tr><td><code>T27</code></td><td>Returnees are pressured to reconcile before receiving housing.</td><td>Housing remains unconditional; reconciliation stays voluntary.</td></tr><tr><td><code>T28</code></td><td>A community asks for no external intervention and maintains safe local dialogue.</td><td>The non-intervention decision is recorded as a valid outcome.</td></tr><tr><td><code>T29</code></td><td>A peace agreement proposes transfer of Indigenous land without affected-nation authorization.</td><td>The provision is treated as non-binding and outside party authority.</td></tr><tr><td><code>T30</code></td><td>A mediator’s cultural framework causes harm and participants complain.</td><td>Independent review, correction, remedy, and learning follow.</td></tr></tbody></table> <hr> <h1>25. Implementation and Genesis pathway</h1> <h2>25.1 Permitted pre-constitutional work</h2> <p>Before binding authority exists, actors may:</p> <ul><li>publish and translate tools;</li> <li>train voluntary facilitators;</li> <li>maintain opt-in rosters;</li> <li>support invited dialogues and peer learning;</li> <li>test accessibility, translation, scheduling, consent, data minimization, and failure reporting;</li> <li>fund voluntary, locally authorized prevention and reconstruction projects;</li> <li>run tabletop exercises using fictional or consented data;</li> <li>evaluate whether the framework should not be adopted.</li></ul> <h2>25.2 Prohibited pilots</h2> <p>A pilot may not test:</p> <ul><li>covert intelligence collection;</li> <li>population or developmental scoring;</li> <li>compulsory mediation or truth-telling;</li> <li>sanctions, detention, surveillance, or armed peace enforcement;</li> <li>automatic security referral;</li> <li>biometric, blockchain, or identity requirements;</li> <li>funding conditional on ideological or reconciliation outcomes;</li> <li>entry into Indigenous territory without valid invitation;</li> <li>public ranking of communities by peace, trust, cohesion, spiritual maturity, or compliance.</li></ul> <h2>25.3 Authority provenance</h2> <p>Any later body must identify its constituting law, jurisdiction, parties, representation, powers, exclusions, review, financing, data duties, amendment, and dissolution. Successful pilots do not create jurisdiction by performance.</p> <h2>25.4 Transition and dissolution</h2> <p>Temporary coordinating bodies must dissolve, transfer records and assets, and relinquish brand, platform, funding, and appointment control according to Genesis v0.9. Founder, donor, vendor, mediator-network, or religious continuity cannot substitute for public authorization.</p> <hr> <h1>26. Amendment, compatibility, and version control</h1> <p>An amendment that would add intelligence, investigation, compulsory process, custody, sanctions, border, detention, cyber disruption, weapons, force, adjudication, or enforcement power is not an ordinary Peace amendment. It requires the separately valid constitutional process for that power and a new SCPA compatibility review.</p> <p>All implementations must pin the exact versions of Peace, SCPA, Justice, Shield, Kintsugi, Migration, Aurora, Synoptic, Indigenous, Treaty, emergency, and Genesis instruments they use. A later version does not enter automatically.</p> <p>Where an inconsistency arises:</p> <ol><li>rights-preserving, non-coercive action may continue within valid authority;</li> <li>consequential action fails closed;</li> <li>affected people receive notice where possible;</li> <li>the incompatibility is recorded and independently reviewed;</li> <li>no institution may resolve the conflict by expanding its own jurisdiction.</li></ol> <hr> <hr> <h1>Appendix G — Cluster harmonization adoption — controlled patch v1.8.1</h1> <h2>Normative cluster adoption</h2> <p>This version is a controlled conformance patch. It changes interface adoption, record inheritance, transport, cross-framework responsibility, emergency linkage, pairwise specialization, and exact release compatibility. It does not add a police, intelligence, investigation, search, custody, force, cyber, border, sanctions, prosecutorial, adjudicative, military, or emergency power.</p> <p>It normatively adopts:</p> <ul><li><code>SCPA-RIC/0.1</code>, SHA-256 <code>0c5d6083716969ee499afc5027a812f7153410babdd4a8e6f464270f8534c917</code>;</li> <li><code>CFPAE/0.1</code>, SHA-256 <code>c1d591c665dfd3b9c9f30dd61943a38556905c6f1a2128a64220e054149dfb05</code>;</li> <li><code>ESDIB/0.1</code>, SHA-256 <code>6332dba2fe2d01347f5c2432a1af002e0902aa8bba80c7b533bd50ee89cebf30</code>;</li> <li>the exact security-and-coercion cluster release set <code>SCCA/0.1</code>.</li></ul> <p>The following precedence applies only within their functions:</p> <ol><li><code>SCPA/0.1</code> controls action classification, authority separation, safeguards, review, termination, and remedy;</li> <li><code>SCPA-RIC/0.1</code> controls canonical record identity, the inherited 27-field header, access classes, handoff states, lifecycle states, and <code>implements</code> / <code>extends</code> / <code>splits</code> / <code>contains</code> / <code>imports</code> / <code>not_applicable</code> semantics;</li> <li><code>CFPAE/0.1</code> controls compound protective-action identity, topology, explicit acceptance, concurrent responsibility, custody, independent clocks, correction, remedy, and closure;</li> <li><code>ESDIB/0.1</code> controls dual emergency–security linkage without authority, command, clock, or custody merger;</li> <li>an adopted pairwise addendum controls only its named cross-framework route and cannot expand either framework’s powers;</li> <li>this framework continues to control its substantive non-authority, services, programme design, and domain-specific duties.</li></ol> <h2>Mandatory record inheritance</h2> <p>Every domain record that implements, extends, splits, contains, or imports an <code>SCPA-01</code>–<code>SCPA-44</code> record SHALL preserve the canonical identifier, exact SCPA version, full inherited header, access class, linked-record topology, review and expiry clocks, correction history, termination duty, remedy duty, and data-disposition duty. Combining forms or transporting several records in one packet does not combine authorities.</p> <p>An unmapped or incompatible record fails closed. <code>not_applicable</code> requires an action-specific reasoned determination and cannot mean unknown, inconvenient, unsupported by software, deferred, or unfunded.</p> <h2>Mandatory compound-action envelope</h2> <p>A <code>CFPAE/0.1</code> envelope SHALL be instantiated when two or more frameworks, authorities, jurisdictions, action routes, or custody systems coordinate one protective action. The immutable <code>protective_action_cluster_id</code> links the routes but creates no common jurisdiction or command.</p> <p>Each route SHALL retain its own competent authority, legal source, jurisdiction, exact act, SCPA class, record instances, handoff state, affected-person rights, review clock, expiry, custody, correction, remedy, and closure condition. Silence is not acceptance. Partial acceptance transfers only the named function and material. Sender duties survive unless valid law and an accepted record expressly reassign them.</p> <h2>Emergency–security dual interface</h2> <p>An <code>ESDIB/0.1</code> bridge SHALL be instantiated whenever an emergency event and an SCPA-governed action route materially depend on one another. CDEE/ECRC records may establish emergency context, event identity, logistics, or temporary coordination; they cannot satisfy an SCPA authority requirement. SCPA records may authorize a security or protective act; they cannot declare or prolong an emergency.</p> <p>Where an act requires both bases, both remain valid and separately reviewable, and the earlier expiry controls. Continuation after one basis ends requires a recorded detachment to ordinary law and removal of the expired basis’s command, credentials, data access, finance, privileges, and operational dependencies.</p> <h2>Exact release compatibility</h2> <p>This document participates only in the following tested release set:</p> <table><thead><tr><th>Instrument</th><th align="right">Exact version in release set</th></tr></thead><tbody><tr><td>Security, Coercion, and Protective Action Interface</td><td align="right"><code>SCPA/0.1</code></td></tr><tr><td>SCPA Record Inheritance and Conformance Clause</td><td align="right"><code>SCPA-RIC/0.1</code></td></tr><tr><td>Cross-Framework Protective Action Envelope</td><td align="right"><code>CFPAE/0.1</code></td></tr><tr><td>Emergency–Security Dual-Interface Bridge</td><td align="right"><code>ESDIB/0.1</code></td></tr><tr><td>Shield–Migration Addendum</td><td align="right"><code>SATN/0.1</code></td></tr><tr><td>Peace–Kintsugi–Shield Addendum</td><td align="right"><code>PKS-PRUP/0.1</code></td></tr><tr><td>Shield Protocol</td><td align="right"><code>2.0.1</code></td></tr><tr><td>Kintsugi Protocol</td><td align="right"><code>2.2.1</code></td></tr><tr><td>Migration and Human Mobility Framework</td><td align="right"><code>1.1.1</code></td></tr><tr><td>Peace and Conflict Resolution Framework</td><td align="right"><code>1.8.1</code></td></tr><tr><td>Aegis Protocol</td><td align="right"><code>1.3.4</code></td></tr></tbody></table> <p>Exact member hashes, source hashes, schemas, record mappings, trigger rules, and closure requirements are published in <code>security-coercion-cluster-conformance-registry-v0.1.json</code>. A later version, similar title, local fork, or apparently protective amendment is not automatically compatible. Material mismatch blocks the affected cross-framework route pending explicit compatibility review and a recorded manifest update.</p> <h2>Closure and reopening</h2> <p>A compound route cannot close while authority return, release, property or credential return, pending remedy, correction, claims, data disposition, service continuity, Aegis requalification, or unresolved custody remains open. Reopening restores coordination only; it does not reactivate an expired warrant, detention, force authorization, surveillance permission, cyber action, freeze, sanction, transfer, removal order, or emergency power.</p> <h2>Peace-specific pairwise adoption</h2> <p>Peace adopts <code>PKS-PRUP/0.1</code>, SHA-256 <code>19edf79640abb41f1c872f208a2874140fb2e3b18c70cf97f97ae072931c2857</code>. Protected mediation, caucus, ceasefire, spiritual, cultural, survivor, and source material remains non-intelligence unless a separately lawful route is opened. Mediation failure, withdrawal, impasse, refusal, or non-reconciliation is not an adverse security fact.</p> <p>Peace may make consultation-only, protected-support, urgent-protection, or no-referral decisions. An urgent referral moves only minimum necessary facts and creates no investigation, entry, search, custody, force, weapons, command, or Shield authority.</p> <h1>27. Conclusion</h1> <p>Peace is not the absence of dissent, the production of trust, the movement of populations toward a preferred worldview, or the successful integration of every conflict into one global system. Nor is it the soft front end of intelligence, enforcement, sanctions, or political control.</p> <p>Peacebuilding is the disciplined creation of conditions in which people can remain safe enough to disagree, communicate, negotiate, remember, repair, rebuild, and govern their relationships without hidden coercion. It requires material support, cultural humility, legal clarity, survivor choice, Indigenous authority, accessible institutions, protected civic space, and an ability to stop when intervention would do more harm than good.</p> <blockquote><p><strong>The measure of a peace institution is not how many conflicts it absorbs, but whether it expands the parties’ lawful, informed, non-coerced capacity to shape what follows.</strong></p></blockquote> <hr> <h1>Appendix A. Glossary</h1> <ul><li><strong>Peace Support Commons:</strong> Non-sovereign federation supporting standards, training, routing, and learning without command or jurisdiction.</li> <li><strong>Good offices:</strong> Voluntary support establishing communication or process without representing a party.</li> <li><strong>Mediation:</strong> Facilitated negotiation in which the mediator does not impose the outcome.</li> <li><strong>Ceasefire support:</strong> Design, monitoring, clarification, and implementation assistance within consent and legal boundaries.</li> <li><strong>Protective presence:</strong> Non-coercive accompaniment intended to reduce harm; not policing or armed protection.</li> <li><strong>Truth and memory process:</strong> A process preserving accounts, acknowledging harm, or supporting public record without automatically becoming adjudication.</li> <li><strong>Reconciliation:</strong> A voluntary relational or civic process; never a precondition for rights, support, or return.</li> <li><strong>Peace dividend:</strong> Lawfully funded public or reparative investment intended to support durable peace, not political compliance.</li> <li><strong>Protected dialogue information:</strong> Mediation, caucus, spiritual, trauma, or other process information subject to confidentiality and use limits.</li> <li><strong>Security referral:</strong> A narrowly bounded handoff into an SCPA-governed function; not an automatic consequence of tension or impasse.</li></ul> <h1>Appendix B. Minimum mediation mandate template</h1> <p>A mediation mandate should record:</p> <ol><li>engagement and version identifiers;</li> <li>requesters and represented constituencies;</li> <li>issues included and excluded;</li> <li>mediator appointment and removal;</li> <li>authority and non-authority statement;</li> <li>participation and withdrawal;</li> <li>power-imbalance safeguards;</li> <li>legal advice and relationship to proceedings;</li> <li>accessibility, language, disability, child, survivor, and cultural safeguards;</li> <li>confidentiality, disclosure limits, and data disposition;</li> <li>public communication;</li> <li>agreement authority and required approvals;</li> <li>pause, impasse, referral, complaint, and closure.</li></ol> <h1>Appendix C. Minimum ceasefire support package</h1> <p>A ceasefire support package should include <code>PCR-17</code> through <code>PCR-20</code>, plus:</p> <ul><li>command notification without command transfer;</li> <li>civilian and humanitarian safeguards;</li> <li>observer security and independence;</li> <li>source and witness protection;</li> <li>disputed-incident and correction procedures;</li> <li>no-retaliation from unverified reports;</li> <li>separate evidence and legal handoffs;</li> <li>termination, renewal, archive, and public reporting rules.</li></ul> <h1>Appendix D. Protected-information classes</h1> <table><thead><tr><th>Class</th><th>Examples</th><th>Default handling</th></tr></thead><tbody><tr><td>P1 — Public process</td><td>public schedules, signed public agreements</td><td>public, with correction history</td></tr><tr><td>P2 — Restricted administration</td><td>contacts, logistics, accessibility needs</td><td>purpose-limited access</td></tr><tr><td>P3 — Confidential dialogue</td><td>caucus notes, exploratory proposals</td><td>mediator/process access only</td></tr><tr><td>P4 — High-protection</td><td>survivor, child, asylum, trauma, spiritual, source information</td><td>named access, strong minimization</td></tr><tr><td>P5 — Affected-nation protected</td><td>Indigenous knowledge, sacred material, nation-controlled records</td><td>nation-defined custody and transfer</td></tr><tr><td>P6 — Potential evidence</td><td>separately preserved material with legal relevance</td><td>no transfer without valid legal route</td></tr></tbody></table> <h1>Appendix E. Cross-framework referral envelope</h1> <p>Every consequential referral should state:</p> <ul><li>engagement and event identifiers;</li> <li>sending and receiving functions;</li> <li>exact requested action;</li> <li>authority known and authority still required;</li> <li>information included and expressly excluded;</li> <li>consent and notice status;</li> <li>protected persons and sources;</li> <li>urgency and alternatives;</li> <li>receipt, deficiency, acceptance, rejection, or closure;</li> <li>continuing sender duties;</li> <li>data disposition and correction;</li> <li>complaint and remedy routes.</li></ul> <h1>Appendix F. Change log from v1.7</h1> <p>Version 1.8:</p> <ul><li>replaces the framework-created Global Peace Council with a non-sovereign Peace Support Commons;</li> <li>removes automatic or mandatory GCRSD roles and spiritual-percentage triggers;</li> <li>removes Spiral Dynamics and developmental labels from operational classification;</li> <li>removes AI conflict prediction from intelligence systems;</li> <li>removes fixed trust, cohesion, approval, and values-transformation targets;</li> <li>removes peace-enforcement and sanctions functions;</li> <li>separates mediation, ceasefire, truth, justice, security, migration, community safety, and reconstruction;</li> <li>adds SCPA-compliant urgent-protection and referral firewalls;</li> <li>protects mediation, trauma, spiritual, survivor, migration, child, and Indigenous information;</li> <li>adds 35 operational records, 44 SCPA mappings, 24 readiness gates, and 30 compound tests;</li> <li>adds explicit termination, data disposition, correction, remedy, version control, and legitimate non-intervention.</li></ul>',1);function c(e){var t=n();o(740),r(e,t)}export{c as default};
